import { arch, platform } from "node:os";
import { CATALOG_DATA } from "./catalog-data.js";
import type { ArchiveFormat } from "./archive.js";

/**
 * The verified tool catalog: a fixed version of each tool, and for
 * each platform the exact file, its SHA-256 and where the binary is inside it. Generated by a person
 * with scripts/tools/refresh-catalog.mjs (who reviews the diff); never fetched or changed at runtime.
 */

export type Platform = "linux-x64" | "linux-arm64" | "darwin-x64" | "darwin-arm64" | "win32-x64";

export interface CatalogAsset {
  url: string;
  sha256: string;
  /** Bytes of the download. */
  size: number;
  format: ArchiveFormat;
  /** Path of the executable inside the archive. */
  bin: string;
  /** A data folder inside the archive the tool needs next to it (nmap's scripts and fingerprints). */
  data?: string;
  /** Environment variable that points the tool at that data folder (NMAPDIR). */
  dataEnv?: string;
}

/** A Python tool: installed by uv into its own environment, every package checked by hash. */
export interface UvSpec {
  /** Python version uv provides (its own build: the system's Python is never touched or needed). */
  python: string;
  /** requirements with --hash lines for every package (uv pip compile --generate-hashes). */
  lock: string;
  /** Rough download size, for the space check (Python itself is shared by every uv tool). */
  size: number;
}

export interface CatalogEntry {
  /** The manifest it installs (tool.run's name). */
  name: string;
  version: string;
  via: "release" | "uv";
  uv?: UvSpec;
  /** The project's page, shown next to the license. */
  homepage: string;
  license: string;
  /** The executable's name once installed (in toolbox/bin). */
  binary: string;
  assets: Partial<Record<Platform, CatalogAsset>>;
  /** Oldest version found on the system that Penteos accepts instead of downloading. */
  minVersion?: string;
}

export const CATALOG: readonly CatalogEntry[] = CATALOG_DATA as readonly CatalogEntry[];

export function currentPlatform(): Platform | undefined {
  const key = `${platform()}-${arch()}`;
  return (["linux-x64", "linux-arm64", "darwin-x64", "darwin-arm64", "win32-x64"] as const).find((p) => p === key);
}

export function catalogEntry(name: string): CatalogEntry | undefined {
  return CATALOG.find((e) => e.name === name);
}

/** The entry and the file for this machine, when the catalog has one. */
export function catalogAsset(name: string, on = currentPlatform()): { entry: CatalogEntry; asset: CatalogAsset } | undefined {
  const entry = catalogEntry(name);
  const asset = entry && on ? entry.assets[on] : undefined;
  return entry && asset ? { entry, asset } : undefined;
}

/** "1.6.10" ≥ "1.6.9": numeric parts compared in order; anything after them is ignored. */
export function versionAtLeast(found: string, min: string): boolean {
  const parts = (v: string) => (/\d+(\.\d+)*/.exec(v)?.[0] ?? "0").split(".").map(Number);
  const a = parts(found);
  const b = parts(min);
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const x = a[i] ?? 0;
    const y = b[i] ?? 0;
    if (x !== y) return x > y;
  }
  return true;
}
